import bisect
import numpy as np
import pandas as pd

def clean_ticks(path):
    df = pd.read_csv(path).dropna(subset=['price'])
    out = df.groupby('t_sec', as_index=False)['price'].mean()
    return out.sort_values('t_sec').reset_index(drop=True)

def price_at(df, t):
    ts, ps = df['t_sec'].tolist(), df['price'].tolist()
    if t <= ts[0]:
        return ps[0]
    if t >= ts[-1]:
        return ps[-1]
    j = bisect.bisect_right(ts, t)
    if ts[j - 1] == t:
        return ps[j - 1]
    x0, x1, y0, y1 = ts[j - 1], ts[j], ps[j - 1], ps[j]
    return y0 + (y1 - y0) * (t - x0) / (x1 - x0)

def price_at_np(df, t):
    return float(np.interp(t, df['t_sec'], df['price']))
